var BrowserProxy, Hash, Thumblr, async, path, util;

Hash = require('hashish');

require('colors');

async = require('async');

BrowserProxy = require('./browser_proxy');

path = require('path');

util = require('util');

Thumblr = (function() {

  Thumblr._defaults = {
    viewportSize: {
      width: 1024,
      height: 768
    },
    zoomFactor: 0.5,
    formatter: "thumb_%d.png"
  };

  Thumblr.prototype.browserOptions = {};

  Thumblr.prototype.queue = null;

  function Thumblr(opts, callback) {
    if (opts == null) {
      opts = {};
    }
    this.browserOptions = Hash.merge(Thumblr._defaults, opts);
    this.queue = [];
  }

  Thumblr.prototype.addJob = function(outputPath, urlList) {
    var job;
    job = this._makeJob(outputPath, urlList);
    this.queue = this.queue.concat(job);
    return job;
  };

  Thumblr.prototype.run = function(callback) {
    var _startTime,
      _this = this;
    _startTime = process.hrtime();
    return async.forEachSeries(this.queue, function(item, callback) {
      return _this._runJob(item, callback);
    }, function(err) {
      console.log("\nAll thumbs processed in %s milliseconds", String(process.hrtime(_startTime)).green);
      return callback(err);
    });
  };

  Thumblr.prototype._makeJob = function(outputPath, urlList) {
    return {
      path: outputPath,
      urls: urlList
    };
  };

  Thumblr.prototype._runJob = function(job, callback) {
    var _counter, _startTime,
      _this = this;
    _startTime = process.hrtime();
    _counter = 0;
    return async.forEachSeries(job.urls, function(item, callback) {
      var thumbPath;
      thumbPath = path.join(job.path, util.format(_this.browserOptions.formatter, _counter));
      _counter = _counter + 1;
      return _this._processThumbnail(item, thumbPath, callback);
    }, function(err) {
      if (!err) {
        console.log("Job complete in %s".green.underline, process.hrtime(_startTime));
      }
      return callback(err);
    });
  };

  Thumblr.prototype._processThumbnail = function(url, outputPath, callback) {
    var _startTime;
    console.log("Rendering");
    _startTime = process.hrtime();
    return this._renderThumbnail(url, outputPath, function(err, results) {
      console.log("%s -> %s : %s", url, outputPath, process.hrtime(_startTime));
      return callback(err);
    });
  };

  Thumblr.prototype._renderThumbnail = function(url, outputPath, callback) {
    var _browserProxy;
    _browserProxy = new BrowserProxy({
      zoomFactor: 0.5
    });
    return async.auto({
      visitPage: function(callback, results) {
        return _browserProxy.visit(url, function(err, page) {
          return callback(err, page);
        });
      },
      checkUrl: [
        'visitPage', function(callback, results) {
          return results.visitPage.get('url', function(value) {
            if (value.match(/about:blank/i)) {
              return callback("Bad page. Can't render");
            } else {
              return callback(null, 'success');
            }
          });
        }
      ],
      renderPage: [
        'checkUrl', function(callback, results) {
          return _browserProxy.renderThumbnail(outputPath, callback);
        }
      ],
      closeBrowser: [
        'renderPage', function(callback, results) {
          return _browserProxy.close(callback);
        }
      ]
    }, function(err, results) {
      if (err) {
        throw err;
      }
      console.log("Rendering complete %s\n".green.underline, url);
      return process.nextTick(function() {
        return callback(err, results);
      });
    });
  };

  return Thumblr;

})();

module.exports = Thumblr;

